values ((select id from public.colleges where slug = 'stanford'), 2024, 'rigor-of-record', 'very-important', 'Stanford reads the transcript against the school profile: what counts is whether the student took the hardest load their school offered, not the raw AP count. Five APs at a school offering six reads stronger than nine at a school offering twenty-two.', 'sourced')
