select (select id from public.colleges where slug = 'umich'), 'Fewer AP or honors courses than peers at the same school', 'Michigan''s Early Action pool is read before mid-year grades arrive, so the senior schedule on the application is the evidence of rigor. It carries more weight here than at schools reading in February.', 'curated'
where not exists (select 1 from public.college_rigor_flags where college_id = (select id from public.colleges where slug = 'umich') and title = 'Fewer AP or honors courses than peers at the same school');

insert into public.college_aid_profiles (college_id, sticker_in_state_cents, sticker_out_state_cents, cost_of_attendance_cents, avg_need_grant_cents, merit_aid_available, avg_merit_award_cents, css_profile_required, aid_methodology, meets_full_need, npc_url, citations)
values ((select id from public.colleges where slug = 'umich'), 1778600, 6094600, 3455000, 2410000, true, 700000, true, 'institutional', false, 'https://finaid.umich.edu/net-price-calculator', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, gotchas, evidence)
values ((select id from public.colleges where slug = 'umich'), 'need-based', 6, 'meridies-curated', 'Strong in-state, thin out-of-state', 'The Go Blue Guarantee is genuinely good and genuinely narrow: in-state, income-tested at $125k, and asset-tested on top. Out-of-state need aid is modest against a $70k+ bill.', array['The Go Blue Guarantee is in-state only and is asset-tested as well as income-tested. A family under $125k with a rental property or a paid-off second home does not qualify, and nobody tells them until the package arrives.']::text[], '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, merit_reality, evidence)
values ((select id from public.colleges where slug = 'umich'), 'merit-based', 4, 'meridies-curated', 'Real but small', 'Around $7k typical, and concentrated on out-of-state recruits the university wants. It softens the non-resident price; it does not solve it.', 'Out-of-state merit exists but is small and shrinking — most awards land between $4k and $10k, not full rides.', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, evidence)
values ((select id from public.colleges where slug = 'umich'), 'income-band-consistency', 5, 'meridies-curated', 'A cliff, not a slope', 'The guarantee ends abruptly at $125k and the asset test removes families well under it. A household at $120k with a rental property is treated like one at $200k.', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

