-- University of Texas at Austin

insert into public.colleges (slug, name, initials, brand_color, city, state, country, control, size, acceptance_rate, test_policy, deadlines, website)
values ('ut-austin', 'University of Texas at Austin', 'UT', '#bf5700', 'Austin', 'TX', 'US', 'public', 42444, 0.291, 'required', '{"Regular Decision":"Dec 1"}'::jsonb, 'https://www.utexas.edu')
on conflict (slug) do nothing;

insert into public.college_intel_profiles (college_id, class_rank_considered, class_rank_note, undergrad_enrollment, graduate_enrollment, cds_year, provenance)
values ((select id from public.colleges where slug = 'ut-austin'), null, 'Texas law makes rank decisive: the top 6% of each Texas public high school is automatically admitted to the university. Schools that decline to rank are ranked by UT from the school profile and transcript, so ''we don''t rank'' exempts nobody. Source: Texas top-percent admission statute; UT Austin freshman profile 2025.', 42444, 12200, 2024, 'sourced')
on conflict (college_id) do nothing;

insert into public.college_cds_factors (college_id, cds_year, factor, weight, note, provenance)
values ((select id from public.colleges where slug = 'ut-austin'), 2024, 'rigor-of-record', 'considered', 'House Bill 588 admits the top 6% of a Texas class automatically, so for most residents rank decides admission and rigor never gets a vote. Where rigor does decide is the major review afterwards: a CS applicant without BC calculus and a computing course reads thin at a GPA where a Liberal Arts applicant reads fine.', 'sourced')
on conflict (college_id, cds_year, factor) do nothing;

insert into public.college_majors (college_id, name, provenance, faculty_count, majors_enrolled, curator_note, discipline, admission_model, admission_model_note)
values ((select id from public.colleges where slug = 'ut-austin'), 'Computer Science', 'curated', 62, 1980, 'Because admission is to the major, the department controls its own size. Sections are large but the cohort is stable from first year to graduation — nobody is competing to stay in.', 'Computer Science', 'direct-admit', 'Admitted to CS or not at all. Internal transfer into CS is capped and success rates run in the single digits, so it is not a plan.')
on conflict (college_id, lower(name)) do nothing;

insert into public.college_majors (college_id, name, provenance, faculty_count, majors_enrolled, curator_note)
values ((select id from public.colleges where slug = 'ut-austin'), 'Cockrell School of Engineering', 'curated', 302, 6100, 'Nine departments, each admitting separately. Scale means labs run in shifts; it also means the machine shops are genuinely well equipped.')
on conflict (college_id, lower(name)) do nothing;

insert into public.college_majors (college_id, name, provenance, faculty_count, majors_enrolled, curator_note)
values ((select id from public.colleges where slug = 'ut-austin'), 'McCombs School of Business', 'curated', 118, 1420, 'Cohorted with heavy recruiting infrastructure. The finance track behaves like a separate school inside the school.')
