values ((select id from public.colleges where slug = 'ut-austin'), 'Engineering (Cockrell)', 'curated', 'Engineering (Cockrell)', 'direct-admit', 'Admitted to a named discipline from the start — the opposite of the Texas A&M model, where students enter general engineering and reapply to a discipline after a year.')
