values ((select id from public.colleges where slug = 'nyu'), 6279600, 6279600, 8890800, 4190000, true, 1800000, true, 'institutional', false, 'https://nyu.edu/admissions/financial-aid-and-scholarships/net-price-calculator', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
