insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, gotchas, evidence)
values ((select id from public.colleges where slug = 'nyu'), 'need-based', 3, 'meridies-curated', 'Low — model the cost before the list is final', 'Among the most expensive institutions in the country and among the least generous with need: does not meet full need, gaps routinely, and assesses equity in the primary residence, which most families never model.', array['NYU assesses equity in the primary residence, which most families never model: a paid-down house in an expensive market can add $15–20k a year to the expected contribution. NYU also does not meet full demonstrated need, so gapping is routine even for admitted students.']::text[], '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, merit_reality, evidence)
values ((select id from public.colleges where slug = 'nyu'), 'merit-based', 4, 'meridies-curated', 'Real money, aimed at yield', 'Awards around $18k are common and genuinely reduce the bill — but they land where a family can still finish paying. This is a discount on an $89k sticker, not generosity.', 'Merit awards exist across the schools but are unevenly distributed — most land in CAS, very few in Stern or Tisch.', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, evidence)
values ((select id from public.colleges where slug = 'nyu'), 'income-band-consistency', 3, 'meridies-curated', 'Swings hard by band', 'The $200–250k band often does better than the $110–150k one, because merit is aimed at families who can pay the rest. Quote a single generosity number here and you will be wrong for most of your roster.', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

