insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, gotchas, evidence)
values ((select id from public.colleges where slug = 'caltech'), 'need-based', 9, 'meridies-curated', 'Excellent', 'Meets full need for a very small class, and caps the home-equity assessment against income so it rarely dominates. The friction is timing rather than amount.', array['Home equity is assessed but capped against income, so it rarely dominates. The real friction is timing — packages arrive late enough to squeeze the May 1 decision, and a family comparing offers should ask for an early read.']::text[], '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

insert into public.college_aid_ratings (college_id, kind, rating, rating_kind, label, rationale, merit_reality, evidence)
values ((select id from public.colleges where slug = 'caltech'), 'merit-based', 3, 'meridies-curated', 'A handful of named awards', 'Around $12k for a small number of students. Real, but too rare to plan a list around.', 'Merit awards reach fewer than one in ten students and are modest. Aid is overwhelmingly need-based.', '[{"label":"IPEDS Student Financial Aid 2023–24 and institution aid pages. Generosity rating and equity assumption are Meridies'' own."}]'::jsonb)
on conflict (college_id, kind) do nothing;

