insert into public.high_schools (name, city, state, country, type, enrollment, graduating_class, weighted_scale_max, unweighted_scale_max, weights_gpa, reports_class_rank, ranking_practice, rank_transparency, ap_courses_offered, ib_program, ap_cap, median_sat, median_act, students_per_counselor, matriculation, profile_notes, source_label, provenance)
select 'Lincoln High School', 'Austin', 'TX', 'US', 'public', 2140, 528, 5, 4, true, true, 'decile', null, 24, false, 'Four AP courses per year before senior year', 1290, 28, 412, array['UT Austin — 96 of the class of 2026', 'Texas A&M — 61', 'Texas State — 44', 'Out-of-state four-year — 71']::text[], array['Texas top-10% automatic admission applies, so the decile line is the number that decides UT Austin — not the GPA itself.', 'Rank is released to colleges by decile only; the school will not confirm an exact position, including to families.', 'The 5.0 scale adds a full point for AP and 0.5 for Honors, so a 4.4 here is not comparable to a 4.4 on a 4.5 scale.']::text[], 'Lincoln HS 2026–27 school profile (published PDF) · NCES district filing', 'sourced'
where not exists (select 1 from public.high_schools where lower(name) = lower('Lincoln High School') and state = 'TX');

