select 'Westview Prep', 'Palo Alto', 'CA', 'US', 'independent', 640, 158, 4.33, 4, true, false, 'none', 'not-ranked', 19, false, 'Three AP courses per year; department approval required for a fourth', 1450, 33, 52, array['UC system — 44 of the class of 2026', 'Ivy League and equivalents — 19', 'Liberal arts colleges — 28', 'Out-of-country — 11']::text[], array['The school does not rank and does not publish a distribution, so the percentiles above are Meridies estimates from the published GPA histogram — treat them as a reading, not a report.', 'The +0.33 AP weighting is unusually small, which compresses the top of the class; a 4.1 here sits where a 4.7 would on a 5.0 scale.', 'No class rank means the school profile''s course-rigor statement does the work rank would elsewhere.']::text[], 'Westview Prep 2026–27 school profile (published PDF)', 'sourced'
