insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'Program in Liberal Medical Education (PLME)', null, 'other', 8, 'Brown University — The only combined program with no MCAT and a genuinely open curriculum — it suits a student whose interests are medical without being pre-med-shaped.', 'Length: 8 years — 4 undergraduate, 4 medical. MCAT: Not required. Seat conditions: 3.0 science GPA and continuous enrollment. No reapplication to the medical school.', 'https://www.brown.edu/academics/medical/plme/', 'https://www.brown.edu/academics/medical/plme/'
where not exists (select 1 from public.combined_programs where name = 'Program in Liberal Medical Education (PLME)');

insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'Rice / Baylor Medical Scholars', 'Baylor College of Medicine', 'other', 8, 'Rice University — Roughly six seats a year, so it functions as a reach for anyone — but the research expectation rewards a student who already has lab hours on the activities list.', 'Length: 8 years — 4 undergraduate, 4 medical. MCAT: Required, but no minimum score for scholars in good standing. Seat conditions: 3.5 cumulative GPA, no professional-conduct findings, summer research expectation.', 'https://ga.rice.edu/programs-study/departments-programs/other-programs/medical-scholars-program/', 'https://ga.rice.edu/programs-study/departments-programs/other-programs/medical-scholars-program/'
where not exists (select 1 from public.combined_programs where name = 'Rice / Baylor Medical Scholars');

insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'Pre-Professional Scholars Program in Medicine (PPSP)', null, 'other', 8, 'Case Western Reserve University — The published thresholds make it the most predictable of the eight-year programs: a student either clears the numbers or does not, with no interview lottery after year one.', 'Length: 8 years — 4 undergraduate, 4 medical. MCAT: Required — 508 with no section below 127. Seat conditions: 3.63 cumulative and science GPA maintained every semester.', 'https://case.edu/ugstudies/pre-professional-scholars-program', 'https://case.edu/ugstudies/pre-professional-scholars-program'
where not exists (select 1 from public.combined_programs where name = 'Pre-Professional Scholars Program in Medicine (PPSP)');

insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'BA/MD Six-Year Medical Program', null, 'ba-md', 6, 'University of Missouri–Kansas City — Two years faster and materially cheaper than the alternatives, but the year-round calendar rules out a student whose profile is built on summer programs.', 'Length: 6 years — accelerated, year-round. MCAT: Required before year 5; no minimum for in-state scholars. Seat conditions: Docent-team clinical hours from year one; 2.8 GPA floor with annual review.', 'https://med.umkc.edu/bamd/', 'https://med.umkc.edu/bamd/'
where not exists (select 1 from public.combined_programs where name = 'BA/MD Six-Year Medical Program');

insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'Premedical–Medical Program (PMM)', 'Sidney Kimmel Medical College', 'other', 7, 'Penn State — The seven-year shape keeps a full undergraduate major intact while removing the application year — the usual answer for a strong student who does not want to gamble on an eight-year seat.', 'Length: 7 years — 3 undergraduate, 4 medical. MCAT: Required — 506 minimum. Seat conditions: 3.5 GPA, one summer of clinical or research experience, interview at Jefferson in year 2.', 'https://science.psu.edu/premedical-medical', 'https://science.psu.edu/premedical-medical'
where not exists (select 1 from public.combined_programs where name = 'Premedical–Medical Program (PMM)');

insert into public.combined_programs (name, partner_institution, track, years, description, requirements, url, source_url)
select 'Guaranteed Admission to Medicine (GMED)', null, 'other', 8, 'Virginia Commonwealth University — The lowest MCAT floor in this set and an in-state cost basis, which is why it belongs on a list built around aid rather than prestige.', 'Length: 8 years — 4 undergraduate, 4 medical. MCAT: Required — 500 minimum, one attempt. Seat conditions: 3.5 GPA, Honors College enrollment, Virginia residency strongly weighted.', 'https://honors.vcu.edu/programs/guaranteed-admission/', 'https://honors.vcu.edu/programs/guaranteed-admission/'
where not exists (select 1 from public.combined_programs where name = 'Guaranteed Admission to Medicine (GMED)');

